{
  "name": "telegram-opencode-bot",
  "version": "1.2.0",
  "description": "Bridge between Telegram and a local OpenCode server",
  "keywords": [
    "opencode",
    "telegram",
    "bot",
    "ai",
    "agent",
    "grammy"
  ],
  "license": "MIT",
  "type": "module",
  "main": "telegram_bot_v0.mjs",
  "bin": {
    "telegram-opencode-bot": "telegram_bot_v0.mjs"
  },
  "publishConfig": {
    "access": "public"
  },
  "files": [
    "telegram_bot_v0.mjs",
    "welcome/messages.txt",
    ".env.example",
    "README.md"
  ],
  "scripts": {
    "start": "node telegram_bot_v0.mjs",
    "dev": "node --watch telegram_bot_v0.mjs"
  },
  "engines": {
    "node": ">=18"
  },
  "dependencies": {
    "dotenv": "^16.4.5",
    "grammy": "^1.34.0"
  }
}
